// Real transit data from next-ingress, UTC-first.
const firstItem = $input.first()?.json || {};
const ingressUTC = firstItem.ingress_utc;
// NEVER fall back to a hard-coded sign. If next-ingress did not answer with real
// ephemeris data we abort the run instead of emailing a wrong transit.
if (!firstItem.next_sign || !firstItem.current_sign || !ingressUTC) {
  throw new Error('next-ingress returned no transit data - aborting so no wrong-sign email is sent.');
}
const nextSign = firstItem.next_sign;
const currentSign = firstItem.current_sign;
// Guard against a stale/queued payload: never email about an ingress already past.
if (new Date(ingressUTC).getTime() <= Date.now()) {
  throw new Error('next-ingress returned an ingress in the past - aborting stale run.');
}
const ingressET = firstItem.ingress_et || ingressUTC;
const ingressUTCDisplay = firstItem.ingress_utc_display || ingressUTC;
const zones = firstItem.ingress_local || {};
const timeLine = [ingressUTCDisplay, zones.new_york, zones.los_angeles, zones.london, zones.sydney].filter(Boolean).join(' \u2022 ');
const blogSlug = firstItem.blog_slug || `moon-enters-${nextSign.toLowerCase()}`;
const signImageUrl = firstItem.sign_image_url || `https://moondaylive.com/assets/signs/${nextSign.toLowerCase()}.png`;
const hoursUntil = firstItem.hours_until || 0;
const blueprintUrl = firstItem.blueprint_url || 'https://moondaylive.com/blueprint';

const now = new Date();
const ingressTime = ingressUTC ? new Date(ingressUTC) : now;
const validIngressTime = isNaN(ingressTime.getTime()) ? now : ingressTime;

// LEAD TIME: 10 hours before ingress. This guarantees an overnight/early-morning
// ingress (e.g. 12:13 UTC) still gets its approval email the evening before,
// instead of firing while you are asleep and missing the window entirely.
const LEAD_HOURS = 10;
let postTime = new Date(validIngressTime.getTime() - LEAD_HOURS * 60 * 60 * 1000);

// Quiet hours 7 PM - 5 AM America/New_York.
// IMPORTANT: we only ever move the email EARLIER, never later, so the review
// window can never slide past the ingress itself.
const getNYHour = (d) => parseInt(d.toLocaleString('en-US', { timeZone: 'America/New_York', hour: 'numeric', hour12: false }), 10);
const nyParts = (d) => d.toLocaleString('en-US', { timeZone: 'America/New_York', year: 'numeric', month: '2-digit', day: '2-digit' }).split(',')[0].split('/');
const nyOffset = (y, m, d) => (new Date(`${y}-${m}-${d}T18:30:00`).toLocaleString('en-US', { timeZone: 'America/New_York', timeZoneName: 'short' }).match(/[A-Z]{3,4}$/)[0] === 'EDT' ? '-04:00' : '-05:00');

const localHour = getNYHour(postTime);
if (localHour >= 19 || localHour < 5) {
  // Pull back to 6:30 PM ET on the most recent evening at or before postTime.
  let ref = postTime;
  if (localHour < 5) ref = new Date(postTime.getTime() - 24 * 60 * 60 * 1000);
  const [m, d, y] = nyParts(ref);
  postTime = new Date(`${y}-${m}-${d}T18:30:00${nyOffset(y, m, d)}`);
}

// Never schedule in the past and never after the ingress: send immediately.
if (postTime.getTime() <= now.getTime() + 60000 || postTime.getTime() >= validIngressTime.getTime()) {
  postTime = new Date(now.getTime() + 60000);
}

const blogTitle = `Moon Enters ${nextSign}: What to Feel, Notice, and Release`;
const blogDraft = `As the Moon transitions from ${currentSign} into ${nextSign}, we enter a powerful shift in emotional currents and collective energy. This alignment invites us to reflect on how we ground our inner intuitive realizations into focused, intentional momentum. Explore how this dynamic influences your daily rhythm and emotional landscape as we navigate this celestial threshold together.

The Moon enters ${nextSign} at ${timeLine}. Visit your Moonday blueprint at ${blueprintUrl} to see how this transit touches your personal Lunar Signature.`;

const redditDraft = `Hey r/moondaylive! \ud83c\udf19 The Moon is officially shifting from ${currentSign} into ${nextSign}.

This transition brings a fascinating pivot in our collective emotional weather, moving us from the reflective depths into a renewed wave of initiation and drive.

The Moon enters ${nextSign} at ${timeLine}. How are you tracking this energy today? Drop your thoughts below!

*(Not sure where your natal Moon sits for this transit? Head over to ${blueprintUrl} to run an extensive personal evaluation.)*`;

return [{
  json: {
    resumeAt: postTime.toISOString(),
    currentSign,
    nextSign,
    ingressUTC: ingressUTC || new Date().toISOString(),
    ingressET,
    ingressUTCDisplay,
    timeLine,
    label: `Moon ${currentSign} \u2192 ${nextSign}`,
    hoursUntilIngress: hoursUntil,
    blog_slug: blogSlug,
    blog_title: blogTitle,
    sign_image_url: signImageUrl,
    blueprint_url: blueprintUrl,
    blog_content: blogDraft,
    reddit_content: redditDraft
  }
}];

