// FRESHNESS GUARD - runs immediately before the approval email is sent.
// A resumed Wait execution can carry a payload that was built hours or days ago.
// We re-read next-ingress here and refuse to email unless it still matches.
const fresh = $input.first()?.json || {};
const planned = $('Code in JavaScript').item.json;

if (!fresh.next_sign || !fresh.ingress_utc) {
  throw new Error('Freshness guard: next-ingress returned no data - aborting.');
}
if (new Date(fresh.ingress_utc).getTime() <= Date.now()) {
  throw new Error('Freshness guard: next ingress is already in the past - aborting.');
}
if (fresh.next_sign !== planned.nextSign) {
  throw new Error(`Freshness guard: stale run. Queued sign ${planned.nextSign} but the sky is now heading into ${fresh.next_sign} - aborting so no wrong-sign email is sent.`);
}
if (Math.abs(new Date(fresh.ingress_utc).getTime() - new Date(planned.ingressUTC).getTime()) > 60000) {
  throw new Error('Freshness guard: ingress time drifted from the queued payload - aborting.');
}

// Rebuild the human-readable time from the FRESH payload so the email can never
// render an empty "at ." line.
const zones = fresh.ingress_local || {};
const timeLine = [fresh.ingress_utc_display, zones.new_york, zones.los_angeles, zones.london, zones.sydney].filter(Boolean).join(' \u2022 ');
if (!timeLine) {
  throw new Error('Freshness guard: no readable ingress time - aborting.');
}

const blog_content = planned.blog_content.replace(planned.timeLine, timeLine);
const reddit_content = planned.reddit_content.replace(planned.timeLine, timeLine);

return [{ json: { ...planned, timeLine, ingressUTCDisplay: fresh.ingress_utc_display, blog_content, reddit_content } }];
